from collections import defaultdict, deque

def numBusesToDestination(routes, S, T):
    if S == T:
        return 0

    # Map each stop to the list of route indices that include this stop
    stop_to_routes = defaultdict(list)
    for i, route in enumerate(routes):
        for stop in route:
            stop_to_routes[stop].append(i)

    # BFS initialization
    queue = deque([(S, 0)])  # (current_stop, buses_taken)
    visited_stops = {S}
    visited_routes = set()

    while queue:
        current_stop, buses = queue.popleft()

        for route_idx in stop_to_routes[current_stop]:
            if route_idx in visited_routes:
                continue
            visited_routes.add(route_idx)

            # Check all stops in this route
            for next_stop in routes[route_idx]:
                if next_stop == T:
                    return buses + 1

                if next_stop not in visited_stops:
                    visited_stops.add(next_stop)
                    queue.append((next_stop, buses + 1))

    return -1
